	adj [8][8]int

	// for each dot, list of vertices using it
	dotVerts [7][]int
)

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func countEdges(mask int) int {
	// count edges in induced subgraph of vertices in mask
	// vertices are 1..n
	cnt := 0
	for i := 1; i <= n; i++ {
		if mask&(1<<(i-1)) == 0 {
			continue
		}
		for j := i + 1; j <= n; j++ {
			if mask&(1<<(j-1)) == 0 {
				continue
			}
			if adj[i][j] == 1 {
				cnt++
			}
		}
	}
	return cnt
}

func dfsVertex(pos int) {
	if pos > n {
		// all vertices assigned
		total := 0
		for d := 1; d <= 6; d++ {
			if dotCnt[d] == 0 {
				continue
			}
			total += countEdges(dotMask[d])
		}
		if total > best {
			best = total
		}
		return
	}

	// remaining vertices including pos
	rem := n - pos + 1
	// optimistic upper bound: current best + remaining vertices
	// each vertex can contribute at most 1 edge (rough bound)
	if best >= m { // cannot exceed number of edges
		return
	}
	if best >= m { // redundant but safe
		return
	}
	// simple pruning: if even assigning 1 edge per remaining vertex can't beat best
	if best >= m || best >= best+rem {
		// trivial, but keep structure
	}

	for d := 1; d <= 6; d++ {
		if dotCnt[d] == 6 {
			continue
		}
		vDot[pos] = d
		dotCnt[d]++
		dotMask[d] |= 1 << (pos - 1)
		dotVerts[d] = append(dotVerts[d], pos)

		dfsVertex(pos + 1)

		// backtrack
		dotCnt[d]--
		dotMask[d] &^= 1 << (pos - 1)
		dotVerts[d] = dotVerts[d][:len(dotVerts[d])-1]
	}
