	"os"
)

type Edge struct {
	u, v int
}

var (
	n, m int
	edges []Edge

	best int

	// For each vertex: assigned dot (0 if none), and count of incident edges used
	vDot  [8]int
	vUsed [8]int

	// For each domino type (a,b) with 1<=a<=b<=6, index 0..20
	usedDomino [21]bool
)

// map (a,b) to index 0..20
func domIndex(a, b int) int {
	if a > b {
		a, b = b, a
	}
	// counts: 1..6
	// row a has (7-a) entries
	// prefix sum of previous rows: sum_{k=1}^{a-1} (7-k) = (a-1)*(8-a)/2
	return (a-1)*(8-a)/2 + (b - a)
}

func dfs(ei, placed int) {
	if placed > best {
		best = placed
	}
	if ei == m {
		return
	}
	// Upper bound pruning: remaining edges + placed cannot beat best
	if placed + (m-ei) <= best {
		return
	}

	u := edges[ei].u
	v := edges[ei].v

	// Option 1: skip this edge
	dfs(ei+1, placed)

	// Try all domino types and orientations
	for a := 1; a <= 6; a++ {
		for b := a; b <= 6; b++ {
			idx := domIndex(a, b)
			if usedDomino[idx] {
				continue
			}
			usedDomino[idx] = true

			// orientation 1: a -> u, b -> v
			if canPlace(u, a) && canPlace(v, b) {
				place(u, a)
				place(v, b)
				dfs(ei+1, placed+1)
				unplace(u)
				unplace(v)
			}
			// orientation 2: b -> u, a -> v (if a != b, otherwise same)
			if a != b {
				if canPlace(u, b) && canPlace(v, a) {
					place(u, b)
					place(v, a)
					dfs(ei+1, placed+1)
					unplace(u)
					unplace(v)
				}
			}

			usedDomino[idx] = false
		}
	}
}

func canPlace(v, dot int) bool {
	if vDot[v] == 0 || vDot[v] == dot {
		return true
	}
	return false
}

func place(v, dot int) {
	if vDot[v] == 0 {
		vDot[v] = dot
	}
	vUsed[v]++
}

func unplace(v int) {
	vUsed[v]--
	if vUsed[v] == 0 {
		vDot[v] = 0
	}
}

func main() {
	in := bufio.NewReader(os.Stdin)
	fmt.Fscan(in, &n, &m)
	edges = make([]Edge, m)
	for i := 0; i < m; i++ {
		fmt.Fscan(in, &edges[i].u, &edges[i].v)
	}
	best = 0
	dfs(0, 0)
