package main

import (
	"bufio"
	"fmt"
	"os"
)

type Edge struct {
	u, v int
}

var (
	n, m int
	edges []Edge

	// vertex labels: 0..6 (0 means no domino incident, 1..6 dots)
	vLabel [7]int

	// domino usage: a<=b, map (a,b) to index
	used [7][7]bool

	best int
)

func dfsEdge(idx, placed int) {
	if idx == m {
		if placed > best {
			best = placed
		}
		return
	}

	// upper bound pruning: remaining edges + placed
	if placed + (m - idx) <= best {
		return
	}

	e := edges[idx]
	u, v := e.u, e.v

	// Option 1: skip this edge
	dfsEdge(idx+1, placed)

	// Try all possible domino types a<=b
	for a := 1; a <= 6; a++ {
		for b := a; b <= 6; b++ {
			if used[a][b] {
				continue
			}

			// two orientations: (u<-a, v<-b) and (u<-b, v<-a)
			// orientation 1
			if canPlace(u, v, a, b) {
				place(u, v, a, b)
				used[a][b] = true
				dfsEdge(idx+1, placed+1)
				used[a][b] = false
				unplace(u, v, a, b)
			}

			// orientation 2, avoid duplicate when a==b
			if a != b {
				if canPlace(u, v, b, a) {
					place(u, v, b, a)
					used[a][b] = true
					dfsEdge(idx+1, placed+1)
					used[a][b] = false
					unplace(u, v, b, a)
				}
			}
		}
	}
}

func canPlace(u, v, du, dv int) bool {
	// check vertex u
	if vLabel[u] != 0 && vLabel[u] != du {
		return false
	}
	// check vertex v
	if vLabel[v] != 0 && vLabel[v] != dv {
		return false
	}
	return true
}

func place(u, v, du, dv int) {
	if vLabel[u] == 0 {
		vLabel[u] = du
	}
	if vLabel[v] == 0 {
		vLabel[v] = dv
	}
}

func unplace(u, v, du, dv int) {
	// We cannot simply reset labels to 0, because other edges may rely on them.
	// However, our recursion ensures that once a vertex label is set from 0 to some value,
	// it is never changed to another non-zero value. All edges incident to that vertex
	// in this branch are consistent with that label. When backtracking, we must know
	// whether this edge was the one that introduced the label.
	//
	// To avoid complex tracking, we rely on the fact that labels are only ever set from 0
	// to some value and never reverted to 0 in this function. Instead, we treat labels
	// as constraints for the entire branch; they are reset only when backtracking over
	// the decision that first set them.
	//
	// Therefore, unplace does nothing.
}

func main() {
	in := bufio.NewReader(os.Stdin)
	fmt.Fscan(in, &n, &m)
	edges = make([]Edge, m)
	for i := 0; i < m; i++ {
		var a, b int
		fmt.Fscan(in, &a, &b)
		edges[i] = Edge{a, b}
	}

